/* Orçamento U.V.I.: PDF local; não grava dados do cliente no servidor. */
(() => {
  'use strict';
  const BLUE = [14, 57, 126], ORANGE = [239, 125, 0], INK = [30, 45, 65], MUTED = [95, 110, 130];
  const money = value => Number(value || 0).toLocaleString('pt-BR', {style: 'currency', currency: 'BRL'});
  const date = value => value ? value.split('-').reverse().join('/') : 'Não informada';
  function create(draft, unit, energy = {}) {
    if (!window.jspdf?.jsPDF) throw Error('Biblioteca de PDF indisponível. Recarregue a página e tente novamente.');
    if (!unit) throw Error('Selecione a unidade ITOP emissora.');
    const doc = new window.jspdf.jsPDF({unit: 'mm', format: 'a4', compress: true, putOnlyUsedFonts: true});
    const left = 14, right = 196, width = 182, bottom = 276;
    let y = 0;
    const font = (size = 9, bold = false, color = INK) => {
      doc.setFont('helvetica', bold ? 'bold' : 'normal'); doc.setFontSize(size); doc.setTextColor(...color);
    };
    const wrap = (value, maxWidth) => doc.splitTextToSize(String(value ?? ''), maxWidth);
    function header(first = false) {
      doc.setFillColor(...BLUE); doc.rect(0, 0, 210, 3, 'F');
      doc.addImage(LOGO, 'PNG', left, first ? 9 : 8, first ? 66 : 37, first ? 27.65 : 15.5, 'itop-budget-logo', 'FAST');
      font(first ? 19 : 12, true, BLUE); doc.text('ORÇAMENTO COMERCIAL', right, first ? 20 : 15, {align: 'right'});
      font(8, false, MUTED); doc.text(first ? 'Uma proposta para conectar o seu negócio.' : 'ITOP TELECOM · Continuação da proposta', right, first ? 27 : 21, {align: 'right'});
      y = first ? 40 : 31;
      if (first) {
        font(9, true); const lines = wrap(unit[1], width); doc.text(lines, left, y); y += lines.length * 4.2 + 1;
        font(8, false, MUTED); const address = wrap('CNPJ ' + unit[2] + '  |  ' + unit[3] + ' · ' + unit[0], width);
        doc.text(address, left, y); y += address.length * 4 + 5;
      }
      doc.setDrawColor(...ORANGE); doc.setLineWidth(.8); doc.line(left, y, right, y); y += 7;
    }
    const ensure = height => { if (y + height > bottom) { doc.addPage(); header(); return true; } return false; };
    function paragraph(value, {size = 9, bold = false, color = INK} = {}) {
      font(size, bold, color);
      for (const line of wrap(value, width)) { ensure(5); font(size, bold, color); doc.text(line, left, y + 3.8); y += 5; }
      y += 1;
    }
    function section(title) {
      ensure(19); y += 2; font(10, true, BLUE); doc.text(title.toUpperCase(), left, y + 4);
      doc.setDrawColor(220, 227, 236); doc.setLineWidth(.2); doc.line(left, y + 7, right, y + 7); y += 10;
    }
    function pair(aLabel, aValue, bLabel, bValue) {
      font(9); const a = wrap(aValue || 'Não informado', 85), b = wrap(bValue || 'Não informado', 85);
      const h = Math.max(a.length, b.length) * 4.5 + 8; ensure(h);
      font(7, true, MUTED); doc.text(aLabel.toUpperCase(), left, y + 3); doc.text(bLabel.toUpperCase(), 108, y + 3);
      font(9); doc.text(a, left, y + 8); doc.text(b, 108, y + 8); y += h;
    }
    function amount(label, value) {
      font(9); const lines = wrap(label, 125), h = lines.length * 4.5 + 4; ensure(h);
      font(9); doc.text(lines, left + 2, y + 4); font(9, true); doc.text(value, right - 2, y + 4, {align: 'right'}); y += h;
    }
    header(true);
    font(7, true, MUTED); doc.text('NÚMERO DO ORÇAMENTO', left, y + 2);
    font(8); doc.text(wrap(draft.id || '—', width), left, y + 7); y += 11;
    pair('Emissão · horário de Brasília', date(draft.emissao_data) + ' às ' + draft.emissao_hora, 'Validade da proposta', date(draft.validade));
    pair('Consultor responsável', draft.consultor_nome, 'Unidade ITOP', unit[0]);
    section('Dados do cliente');
    paragraph(draft.cliente_nome, {size: 12, bold: true});
    pair('CPF / CNPJ', draft.cliente_documento, 'E-mail', draft.cliente_email);
    pair('Telefone', draft.cliente_telefone, 'WhatsApp', draft.cliente_whatsapp);
    const address = [draft.cliente_endereco, draft.cliente_numero, draft.cliente_bairro, draft.cliente_cidade].filter(Boolean).join(' · ');
    if (address) paragraph('Endereço: ' + address, {size: 9});
    if (draft.produtos.length) {
      section('Serviços propostos');
      const columns = [14, 94, 128, 142, 168, 196];
      function tableHeader() {
        doc.setFillColor(...BLUE); doc.rect(left, y, width, 9, 'F'); font(8, true, [255, 255, 255]);
        doc.text('PRODUTO / SERVIÇO', 17, y + 5.8); doc.text('CATEGORIA', 97, y + 5.8);
        doc.text('QTD.', 135, y + 5.8, {align: 'center'}); doc.text('UNITÁRIO', 165, y + 5.8, {align: 'right'}); doc.text('MENSAL', 193, y + 5.8, {align: 'right'}); y += 9;
      }
      tableHeader();
      draft.produtos.forEach((item, index) => {
        font(8.2); const values = [item.name, item.category, String(item.q), money(item.price), money(item.price * item.q)];
        const cells = values.map((v, i) => wrap(v, columns[i + 1] - columns[i] - 6));
        // Very long descriptions continue on the next page without clipping a row.
        let line = 0, count = Math.max(...cells.map(c => c.length));
        while (line < count) {
          if (y + 8 > bottom) { doc.addPage(); header(); tableHeader(); }
          const fit = Math.max(1, Math.floor((bottom - y - 4) / 4.2));
          const take = Math.min(count - line, fit), h = Math.max(9, take * 4.2 + 4);
          if (index % 2 === 0) { doc.setFillColor(244, 247, 251); doc.rect(left, y, width, h, 'F'); }
          cells.forEach((cell, i) => {
            font(8.2, i === 4); const slice = cell.slice(line, line + take);
            if (slice.length) doc.text(slice, i >= 3 ? columns[i + 1] - 3 : i === 2 ? 135 : columns[i] + 3, y + 5, {align: i >= 3 ? 'right' : i === 2 ? 'center' : 'left'});
          });
          y += h; line += take;
          doc.setDrawColor(223, 229, 238); doc.line(left, y, right, y);
        }
      });
      ensure(24); y += 4; doc.setFillColor(...BLUE); doc.roundedRect(left, y, width, 19, 2, 2, 'F');
      font(9, true, [255, 255, 255]); doc.text('INVESTIMENTO MENSAL REGULAR', left + 5, y + 8);
      font(8, false, [221, 231, 247]); doc.text('Total dos serviços selecionados', left + 5, y + 13);
      font(20, true, [255, 255, 255]); doc.text(money(draft.valor_mensal), right - 5, y + 12, {align: 'right'}); y += 24;
      const promotional = draft.produtos.filter(p => typeof planPromotion === 'function' && planPromotion(p.name));
      if (promotional.length) {
        section('Condições promocionais');
        promotional.forEach(p => paragraph(p.name + ': ' + planPromotion(p.name).label + '. Depois, ' + money(p.price) + '/mês por unidade.', {size: 9}));
        if (typeof promoSchedule === 'function') paragraph(promoSchedule(draft.produtos), {size: 9, bold: true});
        if (typeof firstYearCost === 'function') paragraph('Total dos primeiros 12 meses: ' + money(firstYearCost(draft.produtos)), {size: 9});
        paragraph('A gratuidade e os descontos se aplicam somente ao plano indicado; adicionais são cobrados normalmente.', {size: 8, color: MUTED});
      }
    }
    if (energy.valid) {
      section('Simulação de energia · Cemig + NETZ');
      amount('Conta Cemig atual', money(energy.bill)); amount('Saldo Cemig preservado', money(energy.residual));
      amount('Conta ITOP NETZ estimada', money(energy.newval)); amount('Total estimado das duas contas', money(energy.combined));
      amount('Economia mensal estimada', money(energy.saving));
      if (draft.produtos.length) {
        amount('Custo líquido equivalente do pacote', money(Math.max(0, draft.valor_mensal - energy.saving)));
        if (draft.valor_mensal > 0) amount('Compensação estimada pela economia', (energy.saving / draft.valor_mensal * 100).toLocaleString('pt-BR', {maximumFractionDigits: 1}) + '%');
      }
      paragraph('A economia de energia é estimada e ocorre separadamente. A mensalidade ITOP é cobrada integralmente; a economia não representa desconto no pacote. Valores sujeitos a tributos, encargos e regras da distribuidora.', {size: 8, color: MUTED});
    }
    if (draft.observacoes) { section('Observações comerciais'); paragraph(draft.observacoes); }
    if (draft.retorno_em) paragraph('Retorno previsto: ' + new Date(draft.retorno_em).toLocaleString('pt-BR', {timeZone: 'America/Sao_Paulo'}) + ' (horário de Brasília)', {size: 9});
    y += 3;
    paragraph('Orçamento sujeito à disponibilidade, cobertura, condições comerciais e confirmação de valores.', {size: 8, color: MUTED});
    for (let page = 1; page <= doc.getNumberOfPages(); page++) {
      doc.setPage(page); doc.setDrawColor(220, 227, 236); doc.line(left, 283, right, 283);
      font(7, false, MUTED); doc.text('ITOP TELECOM  |  Orçamento Comercial', left, 288); doc.text(page + ' / ' + doc.getNumberOfPages(), right, 288, {align: 'right'});
    }
    doc.setProperties({title: 'Orçamento Comercial ITOP - ' + draft.cliente_nome, subject: 'Proposta de serviços ITOP', author: unit[1], creator: 'ITOP · U.V.I.'});
    const name = String(draft.cliente_nome).normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/gi, '-').replace(/^-|-$/g, '').slice(0, 70) || 'Cliente';
    return {doc, name: 'Orcamento-ITOP-' + name + '-' + draft.emissao_data + '.pdf'};
  }
  // Logo do anexo, com fundo transparente; incorporada para funcionar sem requisições externas.
  const LOGO = 'data:image/png;base64,';
  window.ITOPBudgetPDF = Object.freeze({create});
})();
